// Weekly difficulty: the UTC weekday picks a tier, the tier names a band of
// the capped human gap (cappedGap: how much harder a day is for the human-like
// bot than for the certifying search), and src/calibration.js (generated by
// scripts/calibrate-difficulty.mjs) maps each (tier, piece) to the generation
// knobs that land that piece in the band. See docs/generation.md.
//
// Route measurements are evidence of tactical pressure, not shortest-path
// bounds or a claim that every winning strategy encounters these decisions.
import { CALIBRATION } from './calibration.js';
import { PIECE_LIVES } from './pieces.js';

// This module imports no game module: src/monster-ai.js reads the tiers while
// it loads, and the rules import the monsters, so a cycle back here (once
// through the human-like bot) left DIFFICULTY_TIERS unset for any page or
// test that imported this module first.
/** The human-like bot (src/human-bot.js) gives up a floor after this many moves. */
export const HUMAN_MOVE_CAP = 40;

/**
 * Tiers from easiest to hardest. `band` is the [low, high] target range of
 * cappedGap() for a certified edition of that tier; neighbors share a
 * boundary. The weekday, not the gap, picks an edition's tier. The bands
 * follow the gaps measured under these rules, with par's steered recruit
 * (docs/generation.md, "Stage 2 bands"): Gentle starts where the easiest
 * bishop and plain pawn layouts sit, Fiendish ends where the hardest layouts
 * reach (13 to 15 for a single candidate; generation picks among four).
 * Bands are 2.5 wide, about two thirds of one setting's day-to-day spread.
 * The rank also sets how smart the monsters are (src/monster-ai.js).
 * `minFloorMoves`: a certified route must spend at least that many moves on
 * every floor (no freebie floors); generation rejects a candidate that clears
 * one faster and tries the next, then the fallback bank. A list of three
 * numbers sets each floor's own minimum instead (floorMinimums; tooling uses
 * that to compare rules).
 */
export const DIFFICULTY_TIERS = Object.freeze({
  gentle: Object.freeze({ rank: 1, name: 'Gentle', band: Object.freeze([2.5, 5]), minFloorMoves: 0 }),
  fair: Object.freeze({ rank: 2, name: 'Fair', band: Object.freeze([5, 7.5]), minFloorMoves: 0 }),
  tricky: Object.freeze({ rank: 3, name: 'Tricky', band: Object.freeze([7.5, 10]), minFloorMoves: 3 }),
  tough: Object.freeze({ rank: 4, name: 'Tough', band: Object.freeze([10, 12.5]), minFloorMoves: 3 }),
  fiendish: Object.freeze({ rank: 5, name: 'Fiendish', band: Object.freeze([12.5, 15]), minFloorMoves: 3 }),
});
export const TIER_IDS = Object.freeze(Object.keys(DIFFICULTY_TIERS));

/** UTC weekday (0 = Sunday) → tier. Monday is easiest; the weekend is hardest. */
export const WEEKDAY_TIERS = Object.freeze(['fiendish', 'gentle', 'fair', 'tricky', 'tough', 'tough', 'fiendish']);

/** The tier of the public edition for a canonical YYYY-MM-DD date. */
export function tierForDate(date) {
  return WEEKDAY_TIERS[new Date(`${date}T12:00:00Z`).getUTCDay()];
}

/** Newspaper label, e.g. "Difficulty: Tough". */
export function tierLabel(date, tier = tierForDate(date)) {
  return `Difficulty: ${DIFFICULTY_TIERS[tier].name}`;
}

/** Knobs used when a (tier, piece) pair has no calibrated row. */
export const DEFAULT_KNOBS = Object.freeze({ obstacleBase: 7, decoys: 2, scatter: 0, guards: 0, screens: 0, minThreatenedDecisions: 2 });

/**
 * Generation knobs for a tier and the day's piece:
 * - obstacleBase: walls on the first floor; each later floor adds one.
 * - decoys (0-4): optional residents beside each floor's targets (usually 2).
 * - minThreatenedDecisions: a certificate must make at least this many moves
 *   with a committed enemy attack lane on the board.
 * - scatter (0/1): non-pawn targets start in the back four rows, off every
 *   line the player's piece covers from its start square (src/rules.js).
 * - guards (0-2): decoys moved beside a target, where they strike a player who takes it.
 * - screens (0-3): walls placed first on the squares that cut the longest open
 *   lines into the targets, so long-range pieces must close in to capture.
 */
export function knobsFor(tier, piece) {
  if (!Object.hasOwn(DIFFICULTY_TIERS, tier)) throw new RangeError('Unknown difficulty tier.');
  return Object.freeze({ ...DEFAULT_KNOBS, ...(CALIBRATION[tier]?.[piece] ?? {}) });
}

/**
 * One number per certified edition, from its certificate's verifier metrics
 * (src/fairness.js verifyWinningRoute) and the day's piece. Higher is harder.
 * Kept for reference beside the tiers' measure (cappedGap): it says how
 * dangerous the certified route was, not how hard a route is to find.
 *
 *   pressure = threatenedDecisions + 2 × narrowEscapes + turns / 4 + 20 × unsafeShare
 *   score    = pressure / √(lives left at the end of the route)
 *
 * - threatenedDecisions: moves made with a committed attack lane on the board;
 * - narrowEscapes: moves where exactly one legal move was safe;
 * - turns / 4: route length, i.e. how much there is to plan;
 * - unsafeShare: unsafe alternatives / legal alternatives over the route, i.e.
 *   how likely a careless move is to cost a life;
 * - lives left: the piece's lives (pawn 8, rook/knight/bishop 2, queen 1)
 *   minus those the route spent (pawn days only). Spare lives forgive mistakes,
 *   with diminishing returns, hence the square root. Without it a pawn day's
 *   long route would always out-score a queen day that ends at the first slip.
 * It measures one witnessed route, not a shortest or forced one.
 */
export function difficultyScore(metrics, piece) {
  const share = metrics.legalAlternatives ? metrics.unsafeAlternatives / metrics.legalAlternatives : 0;
  const pressure = metrics.threatenedDecisions + 2 * metrics.narrowEscapes + metrics.turns / 4 + 20 * share;
  const livesLeft = Math.max(1, PIECE_LIVES[piece] - metrics.livesLost);
  return Math.round(pressure / Math.sqrt(livesLeft) * 10) / 10;
}

/**
 * How much harder a day is for a person than for the search, beside
 * difficultyScore (which measures the certified route alone). Per floor: the
 * human-like bot's expected moves there (src/human-bot.js humanPar: the mean
 * of its runs from the floor's standard start, a failed run counting as the
 * whole move cap) minus the certified route's moves. Returns those per floor
 * (`floors`), the share of runs that failed per floor (`failed`) and their sum
 * (`total`), rounded to tenths. Higher is harder. The raw gap, for
 * measurement: one failed floor costs the cap minus the route (about 30), so
 * the bot's blind spots swamp it. The tiers use cappedGap.
 */
export function humanGap({ results, certified }, cap = HUMAN_MOVE_CAP) {
  const round = (value) => Math.round(value * 10) / 10;
  const floors = results.map((runs, floor) => runs.reduce((sum, run) => sum + (run.won ? run.moves : cap), 0) / runs.length - certified[floor]);
  return {
    floors: floors.map(round),
    failed: results.map((runs) => round(runs.filter((run) => !run.won).length / runs.length)),
    total: round(floors.reduce((sum, gap) => sum + gap, 0)),
  };
}

/** In the capped human gap, no run counts more than this many extra moves, and a failed run counts exactly this. */
export const GAP_RUN_CAP = 10;
/**
 * How much each floor counts in the capped human gap: all three the same.
 * The king floor counted half while par's bot left its recruit on Auto there
 * and failed 72% of a bishop's king-floor runs. With the steered recruit par
 * assumes and a king recruit on every king floor, the bot fails 0-18% of
 * king-floor runs, as on floors 1 and 2 (docs/generation.md, "Stage 2 bands").
 */
export const GAP_FLOOR_WEIGHTS = Object.freeze([1, 1, 1]);

/**
 * The capped human gap: what the tiers' bands measure (DIFFICULTY_TIERS),
 * from the human-like bot's runs (src/human-bot.js humanPar: `results`, each
 * floor's runs from its standard start) and the certified route's moves per
 * floor (`certified`). Per run, its moves beyond the route's on that floor,
 * at least 0 (a run that beats the route is as easy as it gets) and at most
 * GAP_RUN_CAP, which is also what a failed run counts; per floor, the mean
 * of its runs; then the floors' sum, weighted by GAP_FLOOR_WEIGHTS and
 * rounded to tenths. 0 is a day the bot plays as well as the search; the
 * most is 30. Unlike humanGap, one hopeless floor (the bot's blind spots,
 * mostly king floors and pawn days) can't swamp the others: it costs at most
 * 10, a slow floor's worth.
 */
export function cappedGap({ results, certified }) {
  const floors = results.map((runs, floor) => runs.reduce((sum, run) => sum
    + (run.won ? Math.min(GAP_RUN_CAP, Math.max(0, run.moves - certified[floor])) : GAP_RUN_CAP), 0) / Math.max(1, runs.length));
  return Math.round(floors.reduce((sum, gap, floor) => sum + (GAP_FLOOR_WEIGHTS[floor] ?? 1) * gap, 0) * 10) / 10;
}

/**
 * Each floor's minimum moves under a freebie rule: a number applies to every
 * floor, a list gives floors 1 to 3 their own (0 or missing: no minimum).
 */
export function floorMinimums(rule) {
  return [0, 1, 2].map((floor) => (Array.isArray(rule) ? rule[floor] ?? 0 : rule ?? 0));
}

/**
 * True when a certified route clears some floor in fewer moves than the
 * tier's `minFloorMoves` (or `minimum`, any floorMinimums rule). `floorMoves`
 * (src/fairness.js) lists the moves each floor took until its challenge was
 * complete.
 */
export function freebieFloor(metrics, tier, minimum = DIFFICULTY_TIERS[tier]?.minFloorMoves ?? 0) {
  const minimums = floorMinimums(minimum);
  return (metrics?.floorMoves ?? []).some((moves, floor) => moves < (minimums[floor] ?? 0));
}

/** Distance from a capped human gap to a tier's band; 0 inside it. */
export function bandDistance(gap, tier) {
  const [low, high] = DIFFICULTY_TIERS[tier].band;
  return gap < low ? low - gap : gap > high ? gap - high : 0;
}
